// Строит запросы к Telegram Bot API по свежим строкам листа «services».
// Вход: строки таблицы (id, name, active) и апдейт из узла «Telegram Trigger».
// Выход: элементы { method, payload } — их отправляет узел «Telegram Bot API».

const PREFIX = 'svc:';          // callback_data = 'svc:<id>'
const MAX_CALLBACK_BYTES = 64;  // лимит Telegram для callback_data
const MAX_BUTTONS = 100;        // лимит Telegram для inline-клавиатуры

const update = $('Telegram Trigger').first().json;

// Заголовки сравниваем без учёта регистра и пробелов: «ID», « Name » и т. п.
const field = (row, name) => {
  const key = Object.keys(row).find((k) => k.trim().toLowerCase() === name);
  return key === undefined ? '' : String(row[key] ?? '').trim();
};
const byteLength = (s) => encodeURIComponent(s).replace(/%[0-9A-F]{2}/g, '_').length;

// Пустые строки и строки без ID или названия пропускаем.
const services = $input.all()
  .map(({ json }) => ({
    id: field(json, 'id'),
    name: field(json, 'name'),
    active: ['true', '1', 'yes', 'да'].includes(field(json, 'active').toLowerCase()),
  }))
  .filter((s) => s.id && s.name);

const send = (chatId, text, extra = {}) => ({
  method: 'sendMessage',
  payload: { chat_id: chatId, text, ...extra },
});

const requests = [];

if (update.callback_query) {
  // Нажатие кнопки: ищем услугу по ID в актуальной таблице, а не по тексту кнопки.
  const query = update.callback_query;
  const data = String(query.data ?? '');
  if (data.startsWith(PREFIX)) {
    const service = services.find((s) => s.active && s.id === data.slice(PREFIX.length));
    const chatId = query.message?.chat?.id ?? query.from.id;
    requests.push(send(chatId, service
      ? `Вы выбрали услугу: ${service.name}`
      : 'Эта услуга больше недоступна. Отправьте /start, чтобы обновить меню.'));
  }
  // Ответ на callback убирает индикатор загрузки на кнопке.
  requests.push({ method: 'answerCallbackQuery', payload: { callback_query_id: query.id } });
} else if (update.message) {
  const chatId = update.message.chat.id;
  if (/^\/start(@\w+)?(\s|$)/.test(update.message.text ?? '')) {
    const active = services.filter((s) => s.active);
    const buttons = active
      .filter((s, i) => active.findIndex((x) => x.id === s.id) === i) // дубли ID — по первой строке
      .filter((s) => byteLength(PREFIX + s.id) <= MAX_CALLBACK_BYTES)
      .slice(0, MAX_BUTTONS)
      .map((s) => [{ text: s.name, callback_data: PREFIX + s.id }]);
    requests.push(buttons.length
      ? send(chatId, 'Выберите услугу:', { reply_markup: { inline_keyboard: buttons } })
      : send(chatId, 'Сейчас нет доступных услуг. Загляните позже.'));
  } else {
    requests.push(send(chatId, 'Отправьте /start, чтобы открыть меню услуг.'));
  }
}

return requests.map((json) => ({ json }));
